#!/usr/bin/env bash
# @@POD@@.sh  -  rebuttal steering jobs for ONE RunPod pod (@@GPU_LABEL@@).
# GENERATED by make_pods.py from pod_template.sh on @@GENERATED@@. Do not edit this file by hand:
# edit pod_template.sh / make_pods.py and regenerate, so the three pod scripts stay identical in logic.
#
# Inside the pod (web terminal), from /workspace:
#   bash @@POD@@.sh start      preflight in the foreground (about 5-10 min: it also installs the pinned
#                              environment and runs torch on the GPU); if every check passes, starts `run`
#                              under nohup and returns. You can then close the browser.
#   bash @@POD@@.sh status     job table, current job, elapsed time, last log lines
#   bash @@POD@@.sh finish     stop the jobs now, upload, verify, then delete (or stop) the pod (detached)
#   bash @@POD@@.sh preflight  only the checks
#   bash @@POD@@.sh dry-run    print every command of the job list without running anything
#   bash @@POD@@.sh reset-clock  restart the @@CAP_HOURS@@ h wall-clock cap (only when YOU restart a run)
# (`run` and `watchdog` are started by `start`; they are not meant to be typed.)
#
# Settings (environment variables, all optional):
#   HF_TOKEN        write token for @@HF_REPO@@ (also needs read access to the gated meta-llama
#                   and google/gemma repos). If unset, the token file ~/.cache/huggingface/token is used.
#   WORK=/workspace results, logs and state live in $WORK/out (keep it on the pod's volume disk)
#   HF_HOME         model cache; default ~/.cache/huggingface (the container disk)
#   STEER_DIR       use a local copy of rebuttal/steer instead of downloading it from the Hub
#   CAP_HOURS=@@CAP_HOURS@@     stop the jobs this many hours after `start` and go to the finish step
#   STALL_MIN=@@STALL_MIN@@     stop the jobs if no new output file appears for this many minutes
#   SELF_TERMINATE=1  after a VERIFIED upload, delete this pod with runpodctl (0: leave it running)
#   UPLOAD=1        0: skip the upload and leave the pod running (capture it yourself)
#   GC=1            delete a model from the cache once no later job needs it
set -uo pipefail

POD="@@POD@@"
HF_REPO="@@HF_REPO@@"
STEER_PREFIX="@@STEER_PREFIX@@"
OUT_PREFIX="@@OUT_PREFIX@@"
J3_REV="@@J3_REV@@"
WORK="${WORK:-/workspace}"
OUT="$WORK/out"
STATE="$WORK/.${POD}_state"
INPUTS="${INPUTS:-$WORK/inputs}"
STEER_DL="$WORK/steer_src"
CONSOLE="$WORK/${POD}.console.log"
# the uploader's own log: OUTSIDE $OUT, because a file inside $OUT that grows during the upload can never
# match its uploaded copy, so the verify step would fail every time (it is uploaded on its own afterwards)
UPLOG="$WORK/${POD}.upload.log"
VENV="${VENV:-/root/${POD}_venv}"
TOOLS_VENV="${TOOLS_VENV:-/root/${POD}_tools_venv}"
export UV_CACHE_DIR="${UV_CACHE_DIR:-/root/.cache/uv}"
CAP_HOURS="${CAP_HOURS:-@@CAP_HOURS@@}"
STALL_MIN="${STALL_MIN:-@@STALL_MIN@@}"
SELF_TERMINATE="${SELF_TERMINATE:-1}"
UPLOAD="${UPLOAD:-1}"
GC="${GC:-1}"
GPU_MIN_MIB="${GPU_MIN_MIB:-@@GPU_MIN_MIB@@}"
RAM_MIN_GB="${RAM_MIN_GB:-@@RAM_MIN_GB@@}"
DISK_NEED_GB="${DISK_NEED_GB:-@@DISK_NEED_GB@@}"
UPLOAD_RETRY_SLEEP="${UPLOAD_RETRY_SLEEP:-1800}"
DELETE_GRACE_S="${DELETE_GRACE_S:-300}"
WATCH_POLL_S="${WATCH_POLL_S:-60}"
WORK_NEED_GB=5
EST_LO_H="@@EST_LO_H@@"
EST_HI_H="@@EST_HI_H@@"
# RunPod gives the pod's environment variables to PID 1 (and the web terminal), not to SSH logins:
# take HF_TOKEN, RUNPOD_API_KEY and RUNPOD_POD_ID from PID 1 when this shell lacks them (never printed).
for _v in HF_TOKEN RUNPOD_API_KEY RUNPOD_POD_ID; do
  if [ -z "${!_v:-}" ] && [ -r /proc/1/environ ]; then
    _val="$(tr '\0' '\n' < /proc/1/environ 2>/dev/null | sed -n "s/^${_v}=//p" | head -1)"
    [ -n "$_val" ] && export "$_v=$_val"
  fi
done
unset _v _val
export HF_HOME="${HF_HOME:-$HOME/.cache/huggingface}"
export HF_HUB_CACHE="${HF_HUB_CACHE:-$HF_HOME/hub}"
export PERSONA_EM_ADAPTER_CACHE="${PERSONA_EM_ADAPTER_CACHE:-/root/.cache/persona_em/adapters}"
export PYTHONDONTWRITEBYTECODE=1 TOKENIZERS_PARALLELISM=false PYTHONUNBUFFERED=1
export HF_HUB_DOWNLOAD_TIMEOUT="${HF_HUB_DOWNLOAD_TIMEOUT:-60}"
SELF="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"
if [ -n "${STEER_DIR:-}" ]; then STEER="$STEER_DIR"; else STEER="$STEER_DL/$STEER_PREFIX"; fi

# ---------------------------------------------------------------------------------------------
# The job list, in run order: J1 controls, then J2 organisms in-domain, then J3. Fields:
# id|phase|family|name|set|out|base|adapter|subfolder|full_ft|directions|act_norm_meta|conditions|
# batch|n_layers|questions|n_per_question|max_new_tokens|prefetch specs|gc after|est_lo_s|est_hi_s
# Paths: STEER:<p> = $STEER/<p> (downloaded rebuttal/steer), INPUTS:<p> = $INPUTS/<p> (HF files
# pinned at revision J3_REV and checked by sha256 in preflight).
# ---------------------------------------------------------------------------------------------
read -r -d '' JOB_TABLE <<'@@EOF_JOBS@@'
@@JOBS_TABLE@@
@@EOF_JOBS@@
JOBS=(); while IFS= read -r _line; do [ -n "${_line// /}" ] && JOBS+=("$_line"); done <<< "$JOB_TABLE"

# Every model repo the jobs read (kind:repo[:subfolder]=base), for the access check.
REPO_SPECS=(@@REPO_SPECS@@)

ts() { date -u +%Y-%m-%dT%H:%M:%SZ; }
log() { echo "[$POD $(ts)] $*"; }
die() { log "FATAL: $*"; exit 1; }
py_tools() { "$TOOLS_VENV/bin/python" -I "$STATE/podtools.py" "$@"; }
expand() { case "$1" in STEER:*) echo "$STEER/${1#STEER:}";; INPUTS:*) echo "$INPUTS/${1#INPUTS:}";; *) echo "$1";; esac; }

write_assets() {
  mkdir -p "$STATE" "$OUT/logs" "$INPUTS"
  cat > "$STATE/podtools.py" <<'@@EOF_PODTOOLS@@'
@@PODTOOLS@@
@@EOF_PODTOOLS@@
  cat > "$STATE/expect_inputs.json" <<'@@EOF_EXPECT_INPUTS@@'
@@EXPECT_INPUTS@@
@@EOF_EXPECT_INPUTS@@
  cat > "$STATE/expect_code.json" <<'@@EOF_EXPECT_CODE@@'
@@EXPECT_CODE@@
@@EOF_EXPECT_CODE@@
  cat > "$STATE/expect_hf.json" <<'@@EOF_EXPECT_HF@@'
@@EXPECT_HF@@
@@EOF_EXPECT_HF@@
  cat > "$STATE/jobs.json" <<'@@EOF_JOBS_JSON@@'
@@JOBS_JSON@@
@@EOF_JOBS_JSON@@
}

# job line -> named fields
parse_job() {
  IFS='|' read -r J_ID J_PHASE J_FAM J_NAME J_SET J_OUT J_BASE J_ADAPTER J_SUB J_FULL J_DIRS J_ANM \
    J_CONDS J_BATCH J_NL J_Q J_NPQ J_MAXTOK J_PREFETCH J_GC J_LO J_HI <<< "$1"
}

# the steering command of the parsed job, as an array
job_cmd() {
  local py="$1"
  CMD=("$py" -I "$STEER/code/steer_causal_multi.py"
       --base "$J_BASE" --adapter "$J_ADAPTER" --family "$J_FAM" --organism "$J_NAME"
       --directions-file "$(expand "$J_DIRS")"
       --layers 0.5 --positions last --alphas 0.15 0.3 0.45 --normalize actfrac
       --conditions $J_CONDS
       --n-per-question "$J_NPQ" --max-new-tokens "$J_MAXTOK" --batch-size "$J_BATCH" --seed 0
       --questions-file "$(expand "$J_Q")" --expect-n-layers "$J_NL" --out "$OUT/$J_OUT")
  [ "$J_SUB" != "-" ] && CMD+=(--adapter-subfolder "$J_SUB")
  [ "$J_FULL" = "1" ] && CMD+=(--gemma-full-ft)
  [ "$J_ANM" != "-" ] && CMD+=(--act-norm-meta "$(expand "$J_ANM")")
  return 0
}

token_setup() {
  if [ -z "${HF_TOKEN:-}" ]; then
    local f
    for f in "$HF_HOME/token" "$HOME/.cache/huggingface/token"; do
      if [ -s "$f" ]; then HF_TOKEN="$(tr -d '[:space:]' < "$f")"; export HF_TOKEN; return 0; fi
    done
    return 1
  fi
  export HF_TOKEN
  return 0
}

free_gb() { df -P -B1G "$1" 2>/dev/null | awk 'NR==2{print $4}'; }

workspace_is_volume() { command -v mountpoint >/dev/null && mountpoint -q "$WORK"; }

# ------------------------------------- runpodctl ---------------------------------------------
RP_SYNTAX=""
rp_detect() {
  RP_SYNTAX=""; RP_MSG=""
  if ! command -v runpodctl >/dev/null 2>&1; then RP_MSG="runpodctl is not installed in this image"; return 1; fi
  if [ -z "${RUNPOD_POD_ID:-}" ]; then RP_MSG="RUNPOD_POD_ID is not set (not a RunPod pod?)"; return 1; fi
  local o
  o="$(timeout 40 runpodctl pod get "$RUNPOD_POD_ID" 2>&1)" && grep -q "$RUNPOD_POD_ID" <<< "$o" && { RP_SYNTAX=new; return 0; }
  o="$(timeout 40 runpodctl get pod "$RUNPOD_POD_ID" 2>&1)" && grep -q "$RUNPOD_POD_ID" <<< "$o" && { RP_SYNTAX=old; return 0; }
  if [ -n "${RUNPOD_API_KEY:-}" ]; then
    # older binaries read only their config file: store the key there once (never printed)
    runpodctl config --apiKey "$RUNPOD_API_KEY" >/dev/null 2>&1 || true
    o="$(timeout 40 runpodctl pod get "$RUNPOD_POD_ID" 2>&1)" && grep -q "$RUNPOD_POD_ID" <<< "$o" && { RP_SYNTAX=new; return 0; }
    o="$(timeout 40 runpodctl get pod "$RUNPOD_POD_ID" 2>&1)" && grep -q "$RUNPOD_POD_ID" <<< "$o" && { RP_SYNTAX=old; return 0; }
  fi
  RP_MSG="runpodctl cannot read this pod (not authenticated): $(tail -c 200 <<< "$o" | tr '\n' ' ')"
  return 1
}
rp_delete() {
  local id="$RUNPOD_POD_ID"
  timeout 60 runpodctl pod remove "$id" && return 0
  timeout 60 runpodctl pod delete "$id" && return 0
  timeout 60 runpodctl remove pod "$id" && return 0
  return 1
}
rp_stop() {
  local id="$RUNPOD_POD_ID"
  timeout 60 runpodctl pod stop "$id" && return 0
  timeout 60 runpodctl stop pod "$id" && return 0
  return 1
}

# ------------------------------------- environments ------------------------------------------
ensure_uv() {
  export PATH="$HOME/.local/bin:$PATH"
  command -v uv >/dev/null 2>&1 && return 0
  python3 -m pip install -q uv >/dev/null 2>&1 || python3 -m pip install -q --break-system-packages uv >/dev/null 2>&1 \
    || (curl -LsSf https://astral.sh/uv/install.sh | sh >/dev/null 2>&1)
  command -v uv >/dev/null 2>&1
}
ensure_tools_venv() {
  [ -x "$TOOLS_VENV/bin/python" ] && "$TOOLS_VENV/bin/python" -c "import huggingface_hub" 2>/dev/null && return 0
  ensure_uv || return 1
  uv venv -q -p 3.12 "$TOOLS_VENV" >/dev/null 2>&1 || return 1
  VIRTUAL_ENV="$TOOLS_VENV" uv pip install -q "huggingface_hub==1.32.0" "hf-xet==1.8.0" >/dev/null 2>&1 || return 1
}
ensure_main_venv() {
  local req="$STEER/code/requirements-pod.txt" mark="$VENV/.pod_env_ok"
  local want; want="$(sha256sum "$req" | cut -c1-64)"
  if [ -f "$mark" ] && [ "$(cat "$mark")" = "$want" ]; then log "venv $VENV already installed"; return 0; fi
  ensure_uv || return 1
  local k
  for k in 1 2 3; do
    log "installing the pinned environment into $VENV (attempt $k; torch cu128, about 5 min)"
    rm -rf "${VENV:?}"
    if uv venv -q -p 3.12 "$VENV" && VIRTUAL_ENV="$VENV" uv pip install -q -r "$req" \
         --extra-index-url https://download.pytorch.org/whl/cu128 --index-strategy unsafe-best-match; then
      if "$VENV/bin/python" -c "import torch,transformers,peft;assert torch.cuda.is_available();x=torch.ones(4,device='cuda');assert float((x*2).sum())==8.0;print('torch',torch.__version__,'cuda',torch.version.cuda,'transformers',transformers.__version__,'peft',peft.__version__,'gpu',torch.cuda.get_device_name(0),'cc',torch.cuda.get_device_capability(0))"; then
        echo "$want" > "$mark"; return 0
      fi
      log "the environment installed but torch cannot use the GPU"
    fi
    sleep 30
  done
  return 1
}

# ------------------------------------- inputs ------------------------------------------------
fetch_inputs() {
  if [ -n "${STEER_DIR:-}" ]; then
    log "using the local rebuttal/steer copy STEER_DIR=$STEER_DIR"
    [ -f "$STATE/steer_rev" ] || echo "local:$STEER_DIR" > "$STATE/steer_rev"
  else
    local rev=""; [ -f "$STATE/steer_rev" ] && rev="$(cat "$STATE/steer_rev")"
    py_tools fetch-steer --repo "$HF_REPO" --prefix "$STEER_PREFIX" --dest "$STEER_DL" \
      --rev-file "$STATE/steer_rev" ${rev:+--revision "$rev"} || return 1
  fi
  py_tools fetch-files --repo "$HF_REPO" --revision "$J3_REV" --dest "$INPUTS" --expect "$STATE/expect_hf.json" || return 1
  return 0
}

# ------------------------------------- preflight ---------------------------------------------
PF_FAIL=0; PF_WARN=0
pf() { # pf PASS|WARN|FAIL message
  echo "  [$1] $2" | tee -a "$OUT/logs/preflight.txt"
  case "$1" in FAIL) PF_FAIL=$((PF_FAIL + 1));; WARN) PF_WARN=$((PF_WARN + 1));; esac
}
preflight() {
  write_assets
  : > "$OUT/logs/preflight.txt"
  log "PREFLIGHT for $POD ($(ts))" | tee -a "$OUT/logs/preflight.txt"
  PF_FAIL=0; PF_WARN=0
  # GPU
  if command -v nvidia-smi >/dev/null 2>&1; then
    local g; g="$(nvidia-smi --query-gpu=name,memory.total,driver_version --format=csv,noheader,nounits 2>/dev/null | head -1)"
    local n; n="$(nvidia-smi -L 2>/dev/null | wc -l)"
    local name mem drv; IFS=',' read -r name mem drv <<< "$g"; mem="${mem// /}"; drv="${drv// /}"
    echo "$name ${mem}MiB driver $drv" > "$STATE/gpu"
    if [ -z "$g" ]; then pf FAIL "nvidia-smi shows no GPU"
    elif [ "${mem%%.*}" -lt "$GPU_MIN_MIB" ]; then pf FAIL "GPU '$name' has ${mem} MiB; this pod needs >= $GPU_MIN_MIB MiB (@@GPU_LABEL@@)"
    elif [ "${drv%%.*}" -lt 570 ]; then pf FAIL "NVIDIA driver $drv < 570: the pinned torch (CUDA 12.8) cannot run; redeploy with the CUDA 12.8+ filter"
    else pf PASS "GPU $name, ${mem} MiB, driver $drv, $n GPU(s) visible (the jobs use GPU 0)"; fi
  else pf FAIL "nvidia-smi not found"; fi
  # host RAM (the LoRA merge runs on the CPU in bf16 before the move to the GPU)
  local mt lim ram
  mt=$(awk '/MemTotal/{print int($2/1048576)}' /proc/meminfo 2>/dev/null || echo 0)
  lim=$(cat /sys/fs/cgroup/memory.max 2>/dev/null || cat /sys/fs/cgroup/memory/memory.limit_in_bytes 2>/dev/null || echo max)
  ram=$mt
  if [[ "$lim" =~ ^[0-9]+$ ]] && [ $((lim / 1073741824)) -lt "$mt" ]; then ram=$((lim / 1073741824)); fi
  if [ "$ram" -lt "$RAM_MIN_GB" ]; then pf FAIL "host RAM ${ram} GB < $RAM_MIN_GB GB needed to merge the largest model on the CPU"
  else pf PASS "host RAM ${ram} GB (need >= $RAM_MIN_GB GB)"; fi
  # disks
  mkdir -p "$HF_HUB_CACHE"
  local fh cached fw
  fh=$(free_gb "$HF_HUB_CACHE"); cached=$(du -s -BG "$HF_HUB_CACHE" 2>/dev/null | awk '{print int($1)}')
  if [ $((fh + cached)) -lt "$DISK_NEED_GB" ]; then
    pf FAIL "model cache $HF_HUB_CACHE: ${fh} GB free + ${cached} GB cached < $DISK_NEED_GB GB needed (raise the container disk)"
  else pf PASS "model cache $HF_HUB_CACHE: ${fh} GB free, ${cached} GB already cached (need $DISK_NEED_GB GB at the peak)"; fi
  fw=$(free_gb "$WORK")
  if [ "${fw:-0}" -lt "$WORK_NEED_GB" ]; then pf FAIL "$WORK has ${fw} GB free; need >= $WORK_NEED_GB GB for results"; else pf PASS "$WORK: ${fw} GB free"; fi
  if workspace_is_volume; then pf PASS "$WORK is its own mount (volume disk): results survive a pod stop"
  else pf WARN "$WORK is NOT a separate volume: a pod stop would erase the results. On an upload failure this pod will therefore NOT stop itself; it retries the upload and keeps billing until you act"; fi
  # token, tools, inputs
  if token_setup; then pf PASS "Hugging Face token found (HF_TOKEN or token file; not printed)"
  else pf FAIL "no Hugging Face token: set HF_TOKEN in the pod's environment variables"; fi
  if ensure_tools_venv; then pf PASS "tools venv $TOOLS_VENV (huggingface_hub 1.32.0)"
  else pf FAIL "could not build the tools venv (uv / pip / network)"; fi
  if [ "$PF_FAIL" -eq 0 ]; then
    if fetch_inputs >> "$OUT/logs/preflight.txt" 2>&1; then
      pf PASS "inputs: rebuttal/steer at $(cat "$STATE/steer_rev"), J2/J3 directions at $J3_REV (sha256 checked)"
      if py_tools verify-files --root "$STEER" --expect "$STATE/expect_inputs.json" >> "$OUT/logs/preflight.txt" 2>&1; then
        pf PASS "question sets, control directions and requirements-pod.txt match the checked sha256 values"
      else pf FAIL "a question set, control directions file or requirements-pod.txt differs from the checked version (see $OUT/logs/preflight.txt; regenerate the pod scripts after changing inputs)"; fi
      if py_tools verify-files --root "$STEER" --expect "$STATE/expect_code.json" >> "$OUT/logs/preflight.txt" 2>&1; then
        pf PASS "steering code matches the version the dry run checked"
      else pf WARN "the steering code differs from the version the dry run checked (allowed; see preflight.txt)"; fi
      if "$TOOLS_VENV/bin/python" -I "$STEER/code/upload_once.py" --check-auth >> "$OUT/logs/preflight.txt" 2>&1; then
        pf PASS "HF_TOKEN can write to $HF_REPO"
      else pf FAIL "HF_TOKEN cannot write to $HF_REPO (see $OUT/logs/preflight.txt)"; fi
      if py_tools repo-check "${REPO_SPECS[@]}" >> "$OUT/logs/preflight.txt" 2>&1; then
        pf PASS "all ${#REPO_SPECS[@]} model repos are readable with this token (gated ones included)"
      else pf FAIL "a model repo is not readable (gated licence not accepted?): $(grep 'FAIL' "$OUT/logs/preflight.txt" | tail -3 | tr '\n' ' ')"; fi
    else pf FAIL "could not download the inputs from $HF_REPO (see $OUT/logs/preflight.txt)"; fi
  fi
  # runpodctl
  if [ "$SELF_TERMINATE" = "1" ]; then
    if rp_detect; then pf PASS "runpodctl can manage this pod ($RUNPOD_POD_ID, ${RP_SYNTAX} CLI): it will delete the pod after a verified upload"
    else pf FAIL "$RP_MSG. Fix: in this terminal run  runpodctl config --apiKey <your RunPod API key>  (or set RUNPOD_API_KEY in the pod's environment), then run start again. Or run with SELF_TERMINATE=0 and stop the pod yourself"; fi
  else
    pf WARN "SELF_TERMINATE=0: the pod will NOT delete itself; stop it yourself after the upload"
  fi
  # the pinned environment, installed HERE (in the foreground, while you are still at the terminal): an
  # install or CUDA failure then shows before you leave, instead of ending the unattended run at once
  if [ "$PF_FAIL" -eq 0 ]; then
    echo "  installing the pinned environment (torch 2.11.0+cu128; about 5 min; log $OUT/logs/install.log)" \
      | tee -a "$OUT/logs/preflight.txt"
    if ensure_main_venv >> "$OUT/logs/install.log" 2>&1; then
      local tl; tl="$(grep -a '^torch ' "$OUT/logs/install.log" | tail -1)"
      pf PASS "pinned environment ready (${tl:-installed and GPU-tested earlier in this container})"
    else pf FAIL "the pinned environment did not install, or torch cannot use this GPU (see $OUT/logs/install.log)"; fi
  fi
  [ "$UPLOAD" = "1" ] || pf WARN "UPLOAD=0: results stay on this pod; nothing is uploaded and the pod is left running"
  echo "  plan: ${#JOBS[@]} jobs, expected $EST_LO_H-$EST_HI_H h, hard cap $CAP_HOURS h, stall limit $STALL_MIN min" | tee -a "$OUT/logs/preflight.txt"
  if [ "$PF_FAIL" -gt 0 ]; then
    echo "PREFLIGHT FAILED: $PF_FAIL problem(s). Nothing was started. Fix them and run: bash $SELF start" | tee -a "$OUT/logs/preflight.txt"
    echo "(The pod bills while it sits here.)"
    return 1
  fi
  echo "PREFLIGHT PASSED ($PF_WARN warning(s))" | tee -a "$OUT/logs/preflight.txt"
  return 0
}

# ------------------------------------- watchdog ----------------------------------------------
alive() { [ -n "${1:-}" ] && kill -0 "$1" 2>/dev/null; }
pidof_file() { [ -f "$1" ] && cat "$1"; }
newest_output() { # epoch of the newest file under $OUT, logs and the sweep excluded
  find "$OUT" \( -path "$OUT/logs" -o -path "$OUT/_swept" \) -prune -o -type f -printf '%T@\n' 2>/dev/null \
    | sort -n | tail -1 | cut -d. -f1
}
set_phase() { echo "$*" > "$STATE/phase"; }
kill_job() {
  local pid; pid="$(pidof_file "$STATE/job.pid")"
  if alive "$pid"; then
    log "stopping the running job (process group $pid)"
    kill -TERM -- "-$pid" 2>/dev/null || kill -TERM "$pid" 2>/dev/null
    local i; for i in $(seq 1 30); do alive "$pid" || break; sleep 2; done
    alive "$pid" && { kill -KILL -- "-$pid" 2>/dev/null || kill -KILL "$pid" 2>/dev/null; }
  fi
  return 0
}
watchdog() {
  echo $$ > "$STATE/watchdog.pid"
  local cap_s=$(( ${CAP_HOURS%.*} * 3600 )) stall_s=$((STALL_MIN * 60))
  [[ "$CAP_HOURS" == *.* ]] && cap_s=$(awk -v h="$CAP_HOURS" 'BEGIN{print int(h*3600)}')
  log "watchdog up: cap ${CAP_HOURS} h from $(date -u -d @"$(cat "$STATE/clock_start")" +%FT%TZ), stall ${STALL_MIN} min"
  while :; do
    [ -f "$STATE/finished" ] && { log "watchdog: finished; exiting"; exit 0; }
    local now start reason="" last ph
    now=$(date +%s); start=$(cat "$STATE/clock_start")
    if [ -f "$STATE/finishing" ]; then
      if ! alive "$(pidof_file "$STATE/finish.pid")" && [ ! -f "$STATE/finished" ]; then
        log "watchdog: the finish step died; running it again (its log goes to $CONSOLE)"
        # to the console log, never into $OUT: nothing inside $OUT may change while it uploads
        finish "watchdog: finish step died" >> "$CONSOLE" 2>&1 &
        wait $! || true
      fi
      sleep "$WATCH_POLL_S"; continue
    fi
    if [ $((now - start)) -ge "$cap_s" ]; then reason="cap: $CAP_HOURS h of wall-clock reached"; fi
    if [ -z "$reason" ]; then
      last=$(newest_output); ph=$(stat -c %Y "$STATE/phase" 2>/dev/null || echo "$start")
      [ -z "$last" ] && last=0; [ "$ph" -gt "$last" ] && last=$ph
      if [ $((now - last)) -ge "$stall_s" ]; then reason="stall: no new output file for $STALL_MIN min (phase: $(cat "$STATE/phase" 2>/dev/null))"; fi
    fi
    if [ -z "$reason" ] && ! alive "$(pidof_file "$STATE/run.pid")"; then reason="the job runner died"; fi
    if [ -n "$reason" ]; then
      log "watchdog: $reason -> stopping the jobs and going to the finish step"
      [ -f "$STATE/STOP" ] || echo "$reason" > "$STATE/STOP"
      kill_job
      local i; for i in $(seq 1 20); do [ -f "$STATE/finishing" ] && break; alive "$(pidof_file "$STATE/run.pid")" || break; sleep 30; done
      if [ ! -f "$STATE/finishing" ]; then
        kill "$(pidof_file "$STATE/run.pid")" 2>/dev/null || true
        log "watchdog: running the finish step (its log goes to $CONSOLE)"
        finish "watchdog: $reason" >> "$CONSOLE" 2>&1 &
        wait $! || true
      fi
    fi
    sleep "$WATCH_POLL_S"
  done
}

# ------------------------------------- jobs --------------------------------------------------
JOBS_TSV="$OUT/logs/jobs.tsv"
record() { # record id attempt rc status start end
  [ -f "$JOBS_TSV" ] || printf 'job\tattempt\trc\tstatus\tstart_utc\tend_utc\tseconds\n' > "$JOBS_TSV"
  printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$1" "$2" "$3" "$4" "$(date -u -d @"$5" +%FT%TZ)" "$(date -u -d @"$6" +%FT%TZ)" "$(($6 - $5))" >> "$JOBS_TSV"
}
rc_status() { case "$1" in 0) echo DONE;; 2) echo REFUSED;; 3) echo FAILED_CELLS;; 124) echo TIMEOUT;; 137|143) echo KILLED;; *) echo CRASHED;; esac; }
later_uses() { # later_uses <index> <repo>: 0 if any job after <index> reads <repo>
  local i k; for ((k = $1 + 1; k < ${#JOBS[@]}; k++)); do
    parse_job "${JOBS[$k]}"
    for i in $J_PREFETCH; do [ "$(echo "$i" | cut -d: -f2 | cut -d= -f1)" = "$2" ] && return 0; done
  done
  return 1
}
prefetch_job() { # prefetch_job <specs...>: 3 attempts, the second and third without Xet
  local k
  for k in 1 2 3; do
    [ -f "$STATE/STOP" ] && return 1
    set_phase "prefetch $J_ID attempt $k"
    if [ "$k" -ge 2 ]; then export HF_HUB_DISABLE_XET=1; fi
    setsid timeout --kill-after=60 40m "$TOOLS_VENV/bin/python" -I "$STATE/podtools.py" prefetch "$@" \
      >> "$OUT/logs/prefetch.log" 2>&1 < /dev/null &
    echo $! > "$STATE/job.pid"; wait $!; local rc=$?
    unset HF_HUB_DISABLE_XET
    [ "$rc" -eq 0 ] && return 0
    log "prefetch attempt $k for $J_ID exited $rc"
    sleep 30
  done
  return 1
}
run_jobs() {
  local i
  for ((i = 0; i < ${#JOBS[@]}; i++)); do
    [ -f "$STATE/STOP" ] && { log "STOP: $(cat "$STATE/STOP")"; return 0; }
    parse_job "${JOBS[$i]}"
    if [ -f "$OUT/$J_OUT/DONE" ]; then log "SKIP $J_ID (DONE already)"; continue; fi
    log "JOB $((i + 1))/${#JOBS[@]} $J_ID (expected $((J_LO / 60))-$((J_HI / 60)) min)"
    local specs=(); read -r -a specs <<< "$J_PREFETCH"
    prefetch_job "${specs[@]}" || log "prefetch did not complete for $J_ID; the job will download what it lacks"
    local attempt rc=1 t0 t1
    for attempt in 1 2; do
      [ -f "$STATE/STOP" ] && break
      set_phase "job $J_ID attempt $attempt"
      job_cmd "$VENV/bin/python"
      t0=$(date +%s)
      { echo "# $(ts) attempt $attempt"; printf '%q ' "${CMD[@]}"; echo; } >> "$OUT/logs/$J_ID.log"
      setsid "${CMD[@]}" >> "$OUT/logs/$J_ID.log" 2>&1 < /dev/null &
      echo $! > "$STATE/job.pid"; wait $!; rc=$?
      t1=$(date +%s)
      record "$J_ID" "$attempt" "$rc" "$(rc_status "$rc")" "$t0" "$t1"
      log "  $J_ID attempt $attempt: exit $rc ($(rc_status "$rc")) after $(( (t1 - t0) / 60 )) min; $(ls "$OUT/$J_OUT/generations/"*.jsonl 2>/dev/null | wc -l)/7 cell files"
      case "$rc" in 1|3) [ -f "$STATE/STOP" ] || { log "  retrying $J_ID once (finished cells are kept)"; continue; };; esac
      break
    done
    rm -f "$STATE/job.pid"
    if [ "$GC" = "1" ]; then
      local s repo; for s in $J_PREFETCH; do
        repo="$(echo "$s" | cut -d: -f2 | cut -d= -f1)"
        later_uses "$i" "$repo" || py_tools gc --hub-cache "$HF_HUB_CACHE" "$repo" >> "$OUT/logs/prefetch.log" 2>&1
      done
      parse_job "${JOBS[$i]}"
    fi
  done
  log "all ${#JOBS[@]} jobs visited"
}

# ------------------------------------- finish ------------------------------------------------
finish() {
  local why="${1:-jobs complete}"
  local n; n=$(( $(cat "$STATE/finish.count" 2>/dev/null || echo 0) + 1 )); echo "$n" > "$STATE/finish.count"
  if [ "$n" -gt 3 ]; then log "the finish step already ran 3 times; giving up (results stay in $OUT)"; touch "$STATE/finished"; return 1; fi
  echo "${BASHPID:-$$}" > "$STATE/finish.pid"
  touch "$STATE/finishing"
  [ -f "$STATE/STOP" ] || echo "$why" > "$STATE/STOP"
  set_phase "finish"
  log "FINISH ($why)"
  kill_job
  token_setup || true
  ensure_tools_venv || log "tools venv missing and could not be rebuilt"
  py_tools status --pod "$POD" --out "$OUT" --state "$STATE" --jobs-tsv "$JOBS_TSV" --jobs-json "$STATE/jobs.json" || true
  cp -f "$STATE"/{steer_rev,gpu,STOP,clock_start} "$OUT/logs/" 2>/dev/null || true
  # capture: every new file outside $OUT that is not a re-downloadable cache, venv or input
  local swept=0
  py_tools sweep --since "$STATE/clock_start" --dest "$OUT/_swept" \
    --exclude "$OUT" --exclude "$VENV" --exclude "$TOOLS_VENV" --exclude "$HF_HOME" --exclude "$HF_HUB_CACHE" \
    --exclude "$UV_CACHE_DIR" --exclude "$STEER_DL" --exclude "$INPUTS" --exclude "$PERSONA_EM_ADAPTER_CACHE" \
    --exclude "$HOME/.cache" --exclude "$HOME/.local" --exclude "$HOME/.triton" --exclude "$HOME/.nv" \
    --exclude "$HOME/.runpod" --exclude "$HOME/.runpod*" --exclude "$HOME/.huggingface" \
    --exclude "$HOME/.ssh" --exclude "$HOME/.config" --exclude "$HOME/.bash_history" \
    --exclude "$HOME/.python_history" --exclude "$HOME/.wget-hsts" --exclude "$HOME/.netrc" \
    --exclude "$STATE/podtools.py" --exclude "$CONSOLE" --exclude "$UPLOG" --exclude "/tmp/torchinductor_*" --exclude "/tmp/uv*" \
    --exclude "/tmp/pip*" --exclude "/tmp/tmp*" --exclude "/tmp/.*" \
    --volume-root "$(workspace_is_volume && echo "$WORK" || echo /nonexistent)" \
    "$WORK" "$HOME" /tmp >> "$OUT/logs/finish.log" 2>&1 || swept=$?
  cp -f "$CONSOLE" "$OUT/logs/console.log" 2>/dev/null || true
  local up_rc=1 report="$OUT.upload_report.json"
  if [ "$UPLOAD" != "1" ]; then
    py_tools manifest --out "$OUT" --hf-path "(not uploaded)" | tee "$WORK/${POD}_FINAL_MANIFEST.txt"
    log "UPLOAD=0: nothing uploaded; the results are in $OUT; the pod is left running"
    touch "$STATE/finished"; return 0
  fi
  local k xet
  for k in 1 2 3 4 5 6 7; do
    # odd rounds: one commit through the LFS path (Xet off); even rounds: the Xet pipeline
    xet=""; [ $((k % 2)) -eq 0 ] && xet="--xet"
    log "upload attempt round $k${xet:+ (Xet)}: $OUT -> $HF_REPO:$OUT_PREFIX/ (log: $UPLOG)"
    # the uploader logs to $UPLOG, outside $OUT: nothing inside $OUT may change while it uploads and verifies
    timeout --kill-after=120 3h "$TOOLS_VENV/bin/python" -I "$STEER/code/upload_once.py" --folder "$OUT" \
      --prefix "$OUT_PREFIX" --attempt-timeout 1800 --max-attempts 4 $xet >> "$UPLOG" 2>&1
    up_rc=$?
    [ "$up_rc" -eq 0 ] && break
    log "upload round $k exited $up_rc (see $UPLOG)"
    # with a volume: two rounds (LFS, then Xet), then stop the pod, which keeps the volume and $OUT.
    # without a volume a stop would erase the only copy: keep retrying instead (the pod keeps billing)
    if { workspace_is_volume && [ "$k" -ge 2 ]; } || [ "$k" -ge 7 ]; then break; fi
    if [ "$k" -eq 1 ]; then sleep 60; else sleep "$UPLOAD_RETRY_SLEEP"; fi
  done
  py_tools manifest --out "$OUT" --report "$report" --hf-path "$HF_REPO:$OUT_PREFIX/" | tee "$WORK/${POD}_FINAL_MANIFEST.txt"
  if [ "$up_rc" -eq 0 ]; then
    py_tools upload-file --repo "$HF_REPO" --file "$report" --path-in-repo "$OUT_PREFIX/_upload_report.json" || true
    py_tools upload-file --repo "$HF_REPO" --file "$UPLOG" --path-in-repo "$OUT_PREFIX/_upload_log.txt" || true
    log "UPLOAD VERIFIED: every file in $OUT is on the Hub with the same size and hash"
    rm -f "$WORK/UPLOAD_FAILED"
    if [ "$swept" -eq 3 ]; then
      # every file the sweep could not copy sits on the volume disk, which a stop keeps
      log "the sweep found files it could not capture, all on the volume (see $OUT/_swept/SWEEP.json): stopping instead of deleting"
      touch "$WORK/NOT_CAPTURED" "$STATE/finished"; [ "$SELF_TERMINATE" = "1" ] && { rp_detect; rp_stop; }
      return 0
    fi
    if [ "$swept" -ne 0 ]; then
      # some uncaptured file is on the container disk, which a stop would erase: leave the pod running
      log "the sweep found files it could not capture on the container disk (see $OUT/_swept/SWEEP.json): the pod is LEFT RUNNING"
      touch "$WORK/NOT_CAPTURED" "$STATE/finished"
      return 0
    fi
    touch "$STATE/finished"
    if [ "$SELF_TERMINATE" = "1" ]; then
      log "deleting pod $RUNPOD_POD_ID now"
      sync; rp_detect >/dev/null 2>&1
      if rp_delete; then
        # a delete that took ends this container within seconds; still running after the grace period means
        # the call returned 0 without deleting (an old or odd runpodctl): stop the pod instead, and say so
        sleep "$DELETE_GRACE_S"
        log "the pod still runs $DELETE_GRACE_S s after the delete call; trying to stop it"
        rp_stop || log "COULD NOT STOP THE POD: stop it in the RunPod console"
        sleep 60
        log "STILL RUNNING after delete and stop: terminate the pod in the RunPod console"
        touch "$WORK/TERMINATE_FAILED"
      else
        log "runpodctl could not delete the pod; trying to stop it"
        rp_stop || { log "COULD NOT STOP THE POD: stop it in the RunPod console"; touch "$WORK/TERMINATE_FAILED"; }
      fi
    else
      log "SELF_TERMINATE=0: done; stop or terminate the pod yourself"
    fi
    return 0
  fi
  echo "upload not verified at $(ts); see $UPLOG and $report" > "$WORK/UPLOAD_FAILED"
  log "UPLOAD NOT VERIFIED: wrote $WORK/UPLOAD_FAILED"
  touch "$STATE/finished"
  if [ "$SELF_TERMINATE" = "1" ] && workspace_is_volume; then
    log "stopping (not deleting) the pod: the volume disk keeps $OUT"
    rp_detect >/dev/null 2>&1; rp_stop || { log "COULD NOT STOP THE POD"; touch "$WORK/TERMINATE_FAILED"; }
  else
    log "the pod is LEFT RUNNING: $WORK is not a volume, so stopping would erase the results"
  fi
  return 1
}

# ------------------------------------- entry points ------------------------------------------
run() {
  write_assets
  exec 9>"$STATE/run.lock"
  flock -n 9 || die "another runner holds $STATE/run.lock (see: bash $SELF status)"
  echo $$ > "$STATE/run.pid"
  [ -f "$STATE/clock_start" ] || date +%s > "$STATE/clock_start"
  log "RUN start (pid $$); clock started $(date -u -d @"$(cat "$STATE/clock_start")" +%FT%TZ)"
  token_setup || log "WARNING: no HF token"
  ensure_tools_venv || log "WARNING: tools venv missing"
  set_phase "start"
  if ! alive "$(pidof_file "$STATE/watchdog.pid")"; then
    setsid bash "$SELF" watchdog >> "$OUT/logs/watchdog.log" 2>&1 < /dev/null &
  fi
  [ -d "$STEER/code" ] || fetch_inputs >> "$OUT/logs/preflight.txt" 2>&1 || { finish "inputs missing"; exit 1; }
  set_phase "install"
  if ! ensure_main_venv >> "$OUT/logs/install.log" 2>&1; then
    log "the pinned environment did not install (see $OUT/logs/install.log)"
    finish "environment install failed"; exit 1
  fi
  log "environment ready: $(tail -1 "$OUT/logs/install.log")"
  run_jobs
  finish "$( [ -f "$STATE/STOP" ] && cat "$STATE/STOP" || echo 'all jobs visited')"
}

start() {
  mkdir -p "$WORK" "$OUT/logs" "$STATE"
  if alive "$(pidof_file "$STATE/run.pid")"; then echo "A run is already active (pid $(cat "$STATE/run.pid")). See: bash $SELF status"; exit 1; fi
  [ -f "$STATE/finished" ] && { echo "This pod already finished (see $WORK/${POD}_FINAL_MANIFEST.txt). To run again: rm -f $STATE/finished $STATE/STOP $STATE/finish.count $STATE/finishing"; exit 1; }
  # the cap counts from the start that launches the runner: an earlier start whose preflight failed (and the
  # time spent fixing it) does not eat the cap. Once a runner has run, the clock is kept (see reset-clock).
  [ -f "$STATE/run.pid" ] || date +%s > "$STATE/clock_start"
  preflight || exit 1
  rm -f "$STATE/STOP"
  nohup setsid bash "$SELF" run >> "$CONSOLE" 2>&1 < /dev/null &
  local i; for i in $(seq 1 20); do alive "$(pidof_file "$STATE/run.pid")" && break; sleep 1; done
  if alive "$(pidof_file "$STATE/run.pid")"; then
    echo
    echo "STARTED $POD (runner pid $(cat "$STATE/run.pid")). You can close this browser tab now."
    echo "  progress:  tail -f $CONSOLE        or   bash $SELF status"
    echo "  expected:  $EST_LO_H-$EST_HI_H h; hard cap $CAP_HOURS h from now; then upload to $HF_REPO:$OUT_PREFIX/"
    [ "$SELF_TERMINATE" = "1" ] && echo "  at the end the pod DELETES ITSELF after a verified upload (it stops instead if the upload fails)."
  else
    echo "The runner did not start; see $CONSOLE"; tail -20 "$CONSOLE"; exit 1
  fi
}

status() {
  echo "== $POD status $(ts)"
  local now; now=$(date +%s)
  [ -f "$STATE/clock_start" ] && echo "elapsed: $(( (now - $(cat "$STATE/clock_start")) / 60 )) min of the $CAP_HOURS h cap"
  echo "runner: $(alive "$(pidof_file "$STATE/run.pid")" && echo "alive (pid $(cat "$STATE/run.pid"))" || echo 'not running')   watchdog: $(alive "$(pidof_file "$STATE/watchdog.pid")" && echo alive || echo 'not running')"
  echo "phase: $(cat "$STATE/phase" 2>/dev/null)"
  [ -f "$STATE/STOP" ] && echo "stop reason: $(cat "$STATE/STOP")"
  [ -f "$STATE/finished" ] && echo "FINISHED (manifest: $WORK/${POD}_FINAL_MANIFEST.txt)"
  [ -f "$WORK/UPLOAD_FAILED" ] && echo "UPLOAD_FAILED: $(cat "$WORK/UPLOAD_FAILED")"
  local i n_done=0
  for ((i = 0; i < ${#JOBS[@]}; i++)); do
    parse_job "${JOBS[$i]}"
    local st="."; [ -f "$OUT/$J_OUT/DONE" ] && { st="DONE"; n_done=$((n_done + 1)); }; [ -f "$OUT/$J_OUT/FAILED" ] && st="FAILED"
    printf '  %-7s %s/7 cells  %s\n' "$st" "$(ls "$OUT/$J_OUT/generations/"*.jsonl 2>/dev/null | wc -l)" "$J_ID"
  done
  echo "jobs DONE: $n_done/${#JOBS[@]}"
  local cur; cur="$(cat "$STATE/phase" 2>/dev/null | awk '{print $2}')"
  [ -n "$cur" ] && [ -f "$OUT/logs/$cur.log" ] && { echo "-- last lines of $OUT/logs/$cur.log"; tail -5 "$OUT/logs/$cur.log"; }
}

dry_run() {
  echo "# DRY RUN of $POD: nothing is executed. WORK=$WORK STEER=$STEER INPUTS=$INPUTS VENV=$VENV"
  echo "# ${#JOBS[@]} jobs; expected $EST_LO_H-$EST_HI_H h; cap $CAP_HOURS h; repos checked in preflight: ${#REPO_SPECS[@]}"
  local i
  for ((i = 0; i < ${#JOBS[@]}; i++)); do
    parse_job "${JOBS[$i]}"
    echo "JOB $((i + 1)) $J_ID  [$J_PHASE] expected $((J_LO / 60))-$((J_HI / 60)) min"
    echo "PREFETCH $J_PREFETCH"
    job_cmd "$VENV/bin/python"
    printf 'CMD'; printf ' %q' "${CMD[@]}"; echo
    local g="" s repo; for s in $J_PREFETCH; do repo="$(echo "$s" | cut -d: -f2 | cut -d= -f1)"; later_uses "$i" "$repo" || g="$g $repo"; done
    parse_job "${JOBS[$i]}"
    echo "GC_AFTER${g:- (none)}"
  done
  echo "FINISH upload_once.py --folder $OUT --prefix $OUT_PREFIX ; verify ; then runpodctl pod remove \$RUNPOD_POD_ID (stop if the upload is not verified)"
}

case "${1:-}" in
  start) start ;;
  run) run ;;
  watchdog) watchdog ;;
  preflight) mkdir -p "$WORK" "$OUT/logs" "$STATE"; [ -f "$STATE/clock_start" ] || date +%s > "$STATE/clock_start"; preflight ;;
  finish) # detached, so closing the browser cannot interrupt the upload
          mkdir -p "$WORK" "$STATE"; nohup setsid bash "$SELF" finish-now >> "$CONSOLE" 2>&1 < /dev/null &
          echo "Finishing in the background: jobs stop, results upload, then the pod deletes itself."
          echo "  watch:  tail -f $CONSOLE" ;;
  finish-now) write_assets; echo "manual finish requested $(ts)" > "$STATE/STOP"
          echo $$ > "$STATE/finish.pid"; touch "$STATE/finishing"   # the watchdog stands down first
          kill_job; kill "$(pidof_file "$STATE/run.pid")" 2>/dev/null; finish "manual finish" ;;
  status) status ;;
  dry-run) dry_run ;;
  reset-clock) mkdir -p "$STATE"; date +%s > "$STATE/clock_start"; echo "clock reset to $(ts)" ;;
  *) sed -n '2,17p' "$SELF"; exit 2 ;;
esac
